import re
from pathlib import Path

ROOT = Path("gelen")
DEST = Path("arsiv")
MEDIA_EXTS = {".jpg", ".jpeg", ".png", ".mp4", ".mov"}

compact_re = re.compile(r"20\d{6}")          # ilk YYYYMMDD (20 ile baslar)
dashed_re = re.compile(r"\b(20\d{2})-(\d{2})-(\d{2})\b")  # YYYY-MM-DD

def find_date(name: str):
    m1 = compact_re.search(name)
    if m1:
        y, mo, d = int(m1.group(0)[:4]), int(m1.group(0)[4:6]), int(m1.group(0)[6:8])
    else:
        m2 = dashed_re.search(name)
        if not m2:
            return None
        y, mo, d = (int(g) for g in m2.groups())
    # guvenli tarih kontrolu
    import datetime
    try:
        datetime.date(y, mo, d)
    except ValueError:
        return None
    return f"{y:04d}/{mo:02d}"

moved = []
for p in sorted(ROOT.rglob("*")):
    if not p.is_file():
        continue
    if p.suffix.lower() not in MEDIA_EXTS:
        continue
    target_dir = None
    d = find_date(p.name)
    if d is not None:
        target_dir = DEST / d
    else:
        target_dir = DEST / "tarihsiz"
    target_dir.mkdir(parents=True, exist_ok=True)
    dest = target_dir / p.name
    # adi zaten var ise uzerine yazma, sekil ekleyerek koru
    if dest.exists():
        dest = dest.with_name(dest.stem + "_1" + dest.suffix)
    p.rename(dest)  # ayni disk icinde, icerik degismez (move)
    moved.append((str(p), str(dest)))

print(f"{len(moved)} dosya tasindi:")
for src, dst in moved:
    print(f"  {src} -> {dst}")

